CREATE TABLE IF NOT EXISTS bms_periods(id uuid PRIMARY KEY, year text NOT NULL, term text NOT NULL CHECK(term IN ('Term 1','Term 2','Term 3')), active boolean NOT NULL DEFAULT false, UNIQUE(year,term));
CREATE UNIQUE INDEX IF NOT EXISTS bms_one_active_period ON bms_periods(active) WHERE active;
CREATE TABLE IF NOT EXISTS bms_classes(id uuid PRIMARY KEY, name text UNIQUE NOT NULL, level text NOT NULL, archived boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS bms_subjects(id uuid PRIMARY KEY, name text UNIQUE NOT NULL, frequency integer NOT NULL DEFAULT 3 CHECK(frequency BETWEEN 1 AND 10), archived boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS bms_users(id uuid PRIMARY KEY, name text NOT NULL, login text UNIQUE NOT NULL, role text NOT NULL CHECK(role IN ('administrator','headteacher','teacher','student')), password_hash text NOT NULL, must_change boolean NOT NULL DEFAULT true, disabled boolean NOT NULL DEFAULT false, failures integer NOT NULL DEFAULT 0, locked_until timestamptz, version integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS bms_students(id uuid PRIMARY KEY REFERENCES bms_users(id), index_number text UNIQUE NOT NULL, class_id uuid NOT NULL REFERENCES bms_classes(id));
CREATE TABLE IF NOT EXISTS bms_enrolments(student_id uuid REFERENCES bms_students(id),period_id uuid REFERENCES bms_periods(id),class_id uuid REFERENCES bms_classes(id),PRIMARY KEY(student_id,period_id));
CREATE TABLE IF NOT EXISTS bms_assignments(id uuid PRIMARY KEY, teacher_id uuid NOT NULL REFERENCES bms_users(id), class_id uuid NOT NULL REFERENCES bms_classes(id), subject_id uuid NOT NULL REFERENCES bms_subjects(id), UNIQUE(teacher_id,class_id,subject_id));
CREATE TABLE IF NOT EXISTS bms_settings(key text PRIMARY KEY, value jsonb NOT NULL);
INSERT INTO bms_settings(key,value) VALUES ('teacher_password_enabled','true') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS bms_attempts(key text PRIMARY KEY, count integer NOT NULL DEFAULT 0, until_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS bms_sessions(id text PRIMARY KEY, user_id uuid NOT NULL REFERENCES bms_users(id), version integer NOT NULL, expires timestamptz NOT NULL, revoked boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS bms_scores(id uuid PRIMARY KEY, student_id uuid NOT NULL REFERENCES bms_students(id), period_id uuid NOT NULL REFERENCES bms_periods(id), class_id uuid NOT NULL REFERENCES bms_classes(id), subject_id uuid NOT NULL REFERENCES bms_subjects(id), exercises jsonb NOT NULL DEFAULT '[]', exam_raw numeric CHECK(exam_raw BETWEEN 0 AND 100), class_score numeric CHECK(class_score BETWEEN 0 AND 30), exam_score numeric CHECK(exam_score BETWEEN 0 AND 70), published boolean NOT NULL DEFAULT false, updated_by uuid REFERENCES bms_users(id), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(student_id,period_id,subject_id));
CREATE TABLE IF NOT EXISTS bms_files(id uuid PRIMARY KEY, name text NOT NULL, mime text NOT NULL, content bytea NOT NULL, size integer NOT NULL CHECK(size BETWEEN 1 AND 4000000));
CREATE TABLE IF NOT EXISTS bms_documents(id uuid PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('scheme','lesson','material','question','assignment','announcement','calendar')), title text NOT NULL, class_id uuid REFERENCES bms_classes(id), subject_id uuid REFERENCES bms_subjects(id), period_id uuid REFERENCES bms_periods(id), level text, owner_id uuid NOT NULL REFERENCES bms_users(id), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','approved','returned')), content jsonb NOT NULL DEFAULT '{}', file_id uuid REFERENCES bms_files(id), feedback text NOT NULL DEFAULT '', vetted_at date, reviewed_by uuid REFERENCES bms_users(id), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS bms_unique_scheme ON bms_documents(subject_id,period_id,level) WHERE kind='scheme';
CREATE TABLE IF NOT EXISTS bms_report_details(student_id uuid REFERENCES bms_students(id),period_id uuid REFERENCES bms_periods(id),attendance_present integer,attendance_possible integer,teacher_remarks text NOT NULL DEFAULT '',headteacher_remarks text NOT NULL DEFAULT '',PRIMARY KEY(student_id,period_id),CHECK(attendance_present>=0 AND attendance_present<=attendance_possible));
CREATE TABLE IF NOT EXISTS bms_audit(id bigserial PRIMARY KEY, actor_id uuid REFERENCES bms_users(id), action text NOT NULL, target text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());

